from kivy.uix.boxlayout import BoxLayoutfrom kivy.uix.gridlayout import GridLayoutfrom kivy.uix.label import Labelfrom kivy.uix.scrollview import ScrollViewfrom kivy.uix.button import Buttonfrom kivy.uix.spinner import Spinnerfrom kivy.uix.popup import Popupfrom kivy.uix.textinput import TextInputimport osimport requestsimport json# --- BULUT AYARI: MAIN.PY ÜZERİNDEN GELEN URL ---def get_firebase_url():    return os.environ.get("FIREBASE_URL", "").strip("/")def hucre_olustur(metin, renk=(1, 1, 1, 1), bold=False, genislik=0.25, halign='center'):    return Label(        text=str(metin), size_hint_x=genislik, size_hint_y=None, height=35,        color=renk, bold=bold, font_size='12sp', halign=halign, valign='middle'    )def ekrani_olustur():    detay_sozlugu = {}     isletme = os.environ.get("SECILI_ISLETME", "AMD")    ana_duzen = BoxLayout(orientation='vertical', padding=[15, 220, 15, 10], spacing=10)        gokyuzu = (0.3, 0.6, 1, 1)    kirmizi = (0.8, 0.2, 0.2, 1)    turuncu = (1, 0.5, 0, 1)    BUTON_FONT = '12sp'    satir1 = BoxLayout(orientation='horizontal', size_hint_y=None, height=80, spacing=8)    ekle_btn = Button(text="Yeni", size_hint_x=0.33, background_color=gokyuzu, background_normal='', bold=True, font_size=BUTON_FONT)    duzenle_btn = Button(text="Düzenle", size_hint_x=0.33, background_color=turuncu, background_normal='', bold=True, font_size=BUTON_FONT)    sil_btn = Button(text="Sil", size_hint_x=0.34, background_color=kirmizi, background_normal='', bold=True, font_size=BUTON_FONT)    satir1.add_widget(ekle_btn); satir1.add_widget(duzenle_btn); satir1.add_widget(sil_btn)    satir2 = BoxLayout(orientation='horizontal', size_hint_y=None, height=80, spacing=8)    tedarikci_secici = Spinner(text='Tedarikçi seç', values=(), size_hint_x=0.7, background_color=gokyuzu, background_normal='', bold=True, font_size=BUTON_FONT)    goruntule_btn = Button(text="Detay", size_hint_x=0.3, background_color=gokyuzu, background_normal='', bold=True, font_size=BUTON_FONT)    satir2.add_widget(tedarikci_secici); satir2.add_widget(goruntule_btn)    ana_duzen.add_widget(satir1); ana_duzen.add_widget(satir2)    ana_scroll = ScrollView(size_hint_y=1)    icerik_kutusu = BoxLayout(orientation='vertical', size_hint_y=None, spacing=15)    icerik_kutusu.bind(minimum_height=icerik_kutusu.setter('height'))    kunye_izgara = GridLayout(cols=2, size_hint_y=None, height=160, spacing=[10, 5], padding=[10, 0, 0, 0])    tablo_baslik = GridLayout(cols=4, size_hint_y=None, height=35, spacing=2)    tablo_verileri = GridLayout(cols=4, size_hint_y=None, spacing=10)    tablo_verileri.bind(minimum_height=tablo_verileri.setter('height'))    icerik_kutusu.add_widget(kunye_izgara); icerik_kutusu.add_widget(tablo_baslik); icerik_kutusu.add_widget(tablo_verileri)    ana_scroll.add_widget(icerik_kutusu); ana_duzen.add_widget(ana_scroll)        def verileri_yukle():        nonlocal detay_sozlugu        isl = os.environ.get("SECILI_ISLETME", "AMD")        url = get_firebase_url()        try:            res = requests.get(f"{url}/{isl}/tedarikciler.json", timeout=5)            if res.status_code == 200 and res.json():                bulut_verisi = res.json()                detay_sozlugu.clear()                for k, icerik in bulut_verisi.items():                    v = icerik.get("veri", "")                    for l in v.split("\n"):                        if "FIRMA" in l:                            f_adi = l.split(":", 1)[1].strip()                            detay_sozlugu[f_adi] = v                            break                tedarikci_secici.values = sorted(list(detay_sozlugu.keys()))        except: pass    def detay_goster(instance):        secilen = tedarikci_secici.text        kunye_izgara.clear_widgets(); tablo_baslik.clear_widgets(); tablo_verileri.clear_widgets()        if secilen in detay_sozlugu:            kunye_izgara.height = 220            lines = detay_sozlugu[secilen].split("\n")            v = {"FIRMA": "", "TEL": "", "ALAN": "", "ADRES": "", "YETKILI": ""}            for l in lines:                if ":" in l:                    anahtar = l.split(":", 1)[0].strip()                    if anahtar in v: v[anahtar] = l.split(":", 1)[1].strip()            bilgi_karti = [("FİRMA", v['FIRMA'], (1, 0.6, 0.2, 1)), ("TELEFON", v['TEL'], (1,1,1,1)),                            ("SEKTÖR", v['ALAN'], (1,1,1,1)), ("ADRES", v['ADRES'], (1,1,1,1))]            for baslik, veri, renk in bilgi_karti:                kunye_izgara.add_widget(Label(text=f"[b]{baslik}[/b] :", markup=True, size_hint_x=None, width=200, color=renk))                kunye_izgara.add_widget(Label(text=str(veri), size_hint_x=1, halign='left'))            for m, g in [("İSİM", 0.3), ("UNVAN", 0.2), ("TEL", 0.2), ("E-POSTA", 0.3)]:                tablo_baslik.add_widget(hucre_olustur(m, (1, 0.7, 0.2, 1), True, g))            if v["YETKILI"]:                for kisi in v["YETKILI"].split(" | "):                    p = [i.strip() for i in kisi.split("-")]                    if len(p) >= 4:                        tablo_verileri.add_widget(hucre_olustur(p[0], genislik=0.3, halign='left'))                        for i in range(1, 4): tablo_verileri.add_widget(hucre_olustur(p[i]))    def silme_onayi(instance):        secilen = tedarikci_secici.text        if not secilen or secilen == 'Tedarikçi seç': return        pop_icerik = BoxLayout(orientation='vertical', spacing=20, padding=20)        pop_icerik.add_widget(Label(text=f"[b]{secilen}[/b]\n\nSilmek istiyor musunuz?", markup=True, halign='center'))        onay_btn = Button(text="SİL", background_color=kirmizi); iptal_btn = Button(text="HAYIR")        butonlar = BoxLayout(spacing=10, size_hint_y=None, height=50)        butonlar.add_widget(onay_btn); butonlar.add_widget(iptal_btn); pop_icerik.add_widget(butonlar)        pop = Popup(title="Kayıt Silme", content=pop_icerik, size_hint=(0.8, 0.4))        def sil_islem(btn):            isl = os.environ.get("SECILI_ISLETME", "AMD")            url = get_firebase_url()            if secilen in detay_sozlugu:                try: requests.delete(f"{url}/{isl}/tedarikciler/{secilen.replace('.', '_')}.json", timeout=5)                except: pass                verileri_yukle(); tedarikci_secici.text = 'Tedarikçi seç'            pop.dismiss()        onay_btn.bind(on_release=sil_islem); iptal_btn.bind(on_release=pop.dismiss); pop.open()    def veri_formu_popup(mod="YENİ", mevcut_veri=None):        form_scroll = ScrollView()        icerik = BoxLayout(orientation='vertical', spacing=8, padding=15, size_hint_y=None)        icerik.bind(minimum_height=icerik.setter('height'))        v = {"FIRMA": "", "TEL": "", "ALAN": "", "ADRES": "", "YETKILI": ""}        if mevcut_veri:            for l in mevcut_veri.split("\n"):                if ":" in l:                    k = l.split(":", 1)[0].strip(); v[k] = l.split(":", 1)[1].strip()        f_ad = TextInput(text=v["FIRMA"], hint_text="Firma Adı", size_hint_y=None, height=80, multiline=False)                # --- AKILLI ODAK KONTROLÜ (İSİM ÇAKIŞMASI) ---        def on_f_ad_focus(instance, value):            if not value and mod == "YENİ": # Odak kaybolunca ve yeniyse                isim = instance.text.strip()                if len(isim) > 1:                    isl = os.environ.get("SECILI_ISLETME", "AMD")                    url = get_firebase_url()                    try:                        res = requests.get(f"{url}/{isl}/tedarikciler/{isim.replace('.', '_')}.json", timeout=3)                        if res.status_code == 200 and res.json() is not None:                            instance.background_color = (1, 0.8, 0.8, 1) # Kırmızımsı                            Popup(title='Kayıt Var', content=Label(text=f'{isim} zaten kayıtlı!'), size_hint=(0.7, 0.2)).open()                        else: instance.background_color = (1, 1, 1, 1) # Beyaz                    except: pass        f_ad.bind(focus=on_f_ad_focus)        f_tel = TextInput(text=v["TEL"], hint_text="Genel Telefon", size_hint_y=None, height=80)        f_alan = TextInput(text=v["ALAN"], hint_text="Sektör / Alan", size_hint_y=None, height=80)        f_adres = TextInput(text=v["ADRES"], hint_text="Adres", size_hint_y=None, height=80, multiline=True)        for w in [Label(text=f"{mod} KAYIT", size_hint_y=None, height=30), f_ad, f_tel, f_alan, f_adres]: icerik.add_widget(w)                yetkili_konteyner = BoxLayout(orientation='vertical', size_hint_y=None, spacing=5)        yetkili_konteyner.bind(minimum_height=yetkili_konteyner.setter('height'))        icerik.add_widget(yetkili_konteyner)        yetkili_inputlar = []        def yetkili_satiri_ekle(mevcut_data=None):            row = BoxLayout(orientation='horizontal', size_hint_y=None, height=80, spacing=4)            y_data = mevcut_data.split(" - ") if mevcut_data else ["", "Unvan", "", ""]            isim = TextInput(text=y_data[0], hint_text="İsim", size_hint_x=0.28)            unv = Spinner(text=y_data[1] if len(y_data)>1 else "Unvan", values=("Genel Müdür", "Satış", "Muhasebe", "Satın Alma"), size_hint_x=0.22)            tel = TextInput(text=y_data[2] if len(y_data)>2 else "", hint_text="Tel", size_hint_x=0.22)            mail = TextInput(text=y_data[3] if len(y_data)>3 else "", hint_text="Mail", size_hint_x=0.28)            row.add_widget(isim); row.add_widget(unv); row.add_widget(tel); row.add_widget(mail)            yetkili_konteyner.add_widget(row)            yetkili_inputlar.append({'inputs': (isim, unv, tel, mail)})        if v["YETKILI"]:            for y in v["YETKILI"].split(" | "): yetkili_satiri_ekle(y)        else: yetkili_satiri_ekle()        btn_bar = BoxLayout(size_hint_y=None, height=60, spacing=10)        btn_e = Button(text="+", size_hint_x=0.2); btn_e.bind(on_release=lambda x: yetkili_satiri_ekle())        btn_bar.add_widget(btn_e); icerik.add_widget(btn_bar)        kaydet = Button(text="KAYDET", background_color=(0.1, 0.7, 0.3, 1), size_hint_y=None, height=80)        iptal = Button(text="KAPAT", background_color=kirmizi, size_hint_y=None, height=80)        icerik.add_widget(kaydet); icerik.add_widget(iptal)        form_scroll.add_widget(icerik); pop = Popup(title="Tedarikçi Formu", content=form_scroll, size_hint=(0.98, 0.95))                def kaydet_islem(btn):            if not f_ad.text.strip() or f_ad.background_color == [1, 0.8, 0.8, 1]: return            isl = os.environ.get("SECILI_ISLETME", "AMD"); url = get_firebase_url()            y_list = [f"{i['inputs'][0].text.strip()} - {i['inputs'][1].text} - {i['inputs'][2].text.strip()} - {i['inputs'][3].text.strip()}" for i in yetkili_inputlar if i['inputs'][0].text.strip()]            yeni_blok = (f"FIRMA    : {f_ad.text.strip()}\nTEL      : {f_tel.text.strip()}\n"                         f"ALAN     : {f_alan.text.strip()}\nADRES    : {f_adres.text.strip()}\n"                         f"YETKILI  : {' | '.join(y_list)}\nNOTLAR   : \n")            if mod == "DÜZENLE" and tedarikci_secici.text in detay_sozlugu:                try: requests.delete(f"{url}/{isl}/tedarikciler/{tedarikci_secici.text.replace('.', '_')}.json", timeout=5)                except: pass            try: requests.put(f"{url}/{isl}/tedarikciler/{f_ad.text.strip().replace('.', '_')}.json", json={"veri": yeni_blok}, timeout=5)            except: pass            verileri_yukle(); pop.dismiss()        kaydet.bind(on_release=kaydet_islem); iptal.bind(on_release=pop.dismiss); pop.open()    ekle_btn.bind(on_release=lambda x: veri_formu_popup(mod="YENİ"))    sil_btn.bind(on_release=silme_onayi)    goruntule_btn.bind(on_release=detay_goster)    duzenle_btn.bind(on_release=lambda x: veri_formu_popup(mod="DÜZENLE", mevcut_veri=detay_sozlugu.get(tedarikci_secici.text)) if tedarikci_secici.text != 'Tedarikçi seç' else None)    verileri_yukle()    return ana_duzen